		if (t > CLK_CNT(IOTIM_TIMER_CLOCK, 500)) { // Servo/Oneshot125
			iodma = calibirq;
			calibirq();
			return;
		}
		
	    m = 3;
		while (t >= CLK_CNT(IOTIM_TIMER_CLOCK,800000)) t >>= 1, --m;

		if (d != m) { // Speed changed need to restart
			d = m;
			n = 1;
			continue;
		}

		n++;
		if(n==4)break;
	}

	m_found = m;
	if(m < 0 || n < 4)
    {
        /* Configure DMA to Single Receive */
        HAL_setIOTIMDMATriggerRXSingle((uint32_t)&dshotbuf1[0],6);
        return;
    }
	
	ioirq = dshotirq;
	iodma = dshotdma;

	// (m value)	DShot Variant	Bit Period
	// 0			DShot150		~6.67µs
	// 1			DShot300		~3.33µs
	// 2			DShot600		~1.67µs
	// 3			DShot1200		~0.83µs
	dshotarr1 = CLK_CNT(IOTIM_TIMER_CLOCK, 75000 << m) - 1; //2 bit time of the DShot bit rate
	dshotarr2 = CLK_CNT(IOTIM_TIMER_CLOCK, 375000 << m) - 1; // Extended DShot Telemetry bit rate is 2.5 times DShot bit rate
	
    DL_Timer_stopCounter(IOTIM_INST);

	/* Now we got the bit timing,so we disable the CC ISR and use the Overflow ISR to detect the gap in frame to enable the*/
	/* configure Phase shift*/
	DL_Timer_clearInterruptStatus(IOTIM_INST , DL_TIMERG_INTERRUPT_LOAD_EVENT|IOTIM_INTERRUPT_EVENT);
    DL_Timer_enableInterrupt(IOTIM_INST , DL_TIMER_INTERRUPT_LOAD_EVENT);

